export default {root:"D:/projexts/moe-next/apps/daemon",test:{maxWorkers:1,testTimeout:30000},plugins:[{name:"ff41-drill",enforce:"pre",transform(source,id){if(!id.replaceAll("\\","/").endsWith("/orchestrator/verifier-database.ts"))return null;for(const [before,after] of PAIRS){if(source.split(before).length!==2)throw new Error("DRILL_OCCURRENCE_MISMATCH");source=source.replace(before,after);}console.log("DRILL_APPLIED:"+NAME);return {code:source,map:null};}}]};

